INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1204', '宇宙人ムームー', '2025年春', 'PR0034', 'TVシリーズ', 24, '『宇宙人ムームー』（うちゅうじんムームー）は、宮下裕樹による日本の漫画作品。『ヤングキングアワーズ』（少年画報社）にて、2019年6月号（4月30日発売）に読み切りが掲載されたのち、同年8月号（6月28日発売）から2026年7月号（同年5月29日発売）まで連載。「スーパースペクタクル×家電あれこれ×にゃんコメディ」を標榜し、猫型異星人と女子大生の同居生活を描くSFコメディである。 2025年4月か', 185070) ON CONFLICT DO NOTHING;
