INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1284', '父は英雄、母は精霊、娘の私は転生者。', '2025年秋', 'PR0006', 'TVシリーズ', 12, '『父は英雄、母は精霊、娘の私は転生者。』（ちちはえいゆう はははせいれい むすめのわたしはてんせいしゃ）は、松浦による日本のライトノベル。小説投稿サイト「小説家になろう」にて2016年9月10日から2020年11月1日まで連載された。略称は「ははのは」。 書籍版はカドカワBOOKS（KADOKAWA）より2018年3月から2022年10月まで刊行された。イラストはkeepoutが担当している。20', 173692) ON CONFLICT DO NOTHING;
