INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1295', 'キミと越えて恋になる', '2025年秋', 'PR0116', 'TVシリーズ', 12, '『キミと越えて恋になる』（きみとこえてこいになる）は、柚樹ちひろによる日本の漫画作品。女性向け漫画アプリである『マンガMee』（集英社）にて2021年5月19日より連載中。 獣人と人間が共存する町を舞台に、人間の女子高生と獣人の男子転校生の恋愛を描く。 2025年10月時点で、コミックス累計発行部数は紙と電子合計で150万部を突破しており、PVは6200万を達成している。また、2025年10月から', 186161) ON CONFLICT DO NOTHING;
