INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH009599', 'AN1204', 'ムームー', 'ムームー  ムームー (衣服) - ハワイで女性の正装とされるゆったりとしたドレス。 ムームー (料理) - パプアニューギニアの伝統料理。イモ、野菜、肉、魚などをバナナなどの葉に包んで、焼き石とともに地面に埋めて蒸し焼きにするもの。 日本語の幼児語（育児語）で虫のこと。 ムームー (企業) - 日本のゲームメーカー。代表作は『がんばれ森川君2号』、『ジャンピングフラッシュ!』シリーズ。『ジャンピ', NULL, NULL, 350716) ON CONFLICT DO NOTHING;
