INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH010593', 'AN1266', 'アントワネット', 'アントワネット（Société des avions et moteurs Antoinette）は、フランスの初期の航空機メーカーである。1904年にレオン・ルヴァヴァスール（Leon Levavasseur, 1863年 - 1922年）とジュール・ガスタンビド（Jules Gastambide）が設立した。会社の名前はガスタンビドの長女の名前からつけられた。Puteauxに設立された。 はじ', NULL, '女性', 374880) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH010594', 'AN1266', 'デュ・バリー夫人', 'デュ・バリー夫人（デュ・バリーふじん, Madame du Barry, 1743年8月19日 - 1793年12月8日）は、ルイ15世の公妾。本名マリ＝ジャンヌ・ベキュー（Marie-Jeanne Bécu）。', NULL, '女性', 374882) ON CONFLICT DO NOTHING;
