INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH010596', 'AN1266', 'スタニスラス', 'スタニスラス（Stanislas）は、スラヴ語起源のフランス語圏の男性名。スタニスラフ、スタニスワフのフランス語形にあたる。', NULL, '男性', 374883) ON CONFLICT DO NOTHING;
