INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH010757', 'AN1271', 'ナズナ', 'ナズナ（薺・撫菜、学名：Capsella bursa-pastoris）は、アブラナ科ナズナ属の越年草。別名、ペンペングサ（ぺんぺん草）、シャミセングサ（三味線草）。田畑や荒れ地、道端など至るところに生え、春から夏にかけて白い花と三角形の果実をつける。春の七草の一つで、若苗や若葉は食用にもなる。ムギ栽培の伝来と共に日本に渡来した史前帰化植物と考えられている。', NULL, '女性', 371954) ON CONFLICT DO NOTHING;
