INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH010766', 'AN1271', 'ミヤ', 'ミヤ  ミヤ (MUCC) - 日本のヴィジュアル系ロックバンド・MUCCのギタリスト、音楽プロデューサー。 ミヤ (作家) - 日本のライトノベル作家。小説投稿サイト「カクヨム」からデビュー。代表作に『妹がブラコンであることを兄だけは知っている。』 ミヤ - 日本の小説家・謎解きクリエイターの雨露山鳥（宮嶌祐生）のYouTube出演時などの名義。上記とは別人。 Miya - 日本のジャズフルート', NULL, '女性', 379903) ON CONFLICT DO NOTHING;
